CREATE TABLE IF NOT EXISTS levels(level INTEGER PRIMARY KEY, name TEXT, base_speed REAL, speed_cap REAL, accent TEXT);
CREATE TABLE IF NOT EXISTS bricks(level INTEGER, row INTEGER, column INTEGER, type TEXT, drop_type TEXT, PRIMARY KEY(level,row,column));
CREATE TABLE IF NOT EXISTS leaderboard(id INTEGER PRIMARY KEY AUTOINCREMENT, initials TEXT, score INTEGER, level INTEGER, achieved_at TEXT, email TEXT);
CREATE TABLE IF NOT EXISTS constants(key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE IF NOT EXISTS tokens(token TEXT PRIMARY KEY, user_id INTEGER, created_at TEXT, revoked_at TEXT);
CREATE TABLE IF NOT EXISTS runs(run_id TEXT PRIMARY KEY, user_id INTEGER, status TEXT, revision INTEGER, snapshot_json TEXT, updated_at TEXT, finished_at TEXT, operation_id TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS run_receipts(operation_id TEXT PRIMARY KEY, user_id INTEGER, status_code INTEGER, response_json TEXT, payload_hash TEXT, created_at TEXT);
CREATE TABLE IF NOT EXISTS terminal_runs(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, run_id TEXT, outcome TEXT, level INTEGER, score INTEGER, finished_at TEXT, snapshot_json TEXT);
''')
for sheet in wb.sheetnames:
    ws = wb[sheet]
    rows = list(ws.iter_rows(values_only=True))
    headers = rows[0]
    for row in rows[1:]:
        data = dict(zip(headers,row))
        if sheet=='Users':
            salt = hashlib.sha256(f"{data['email']}|salt".encode()).hexdigest()[:16]
            ph = hashlib.sha256((salt+'password123').encode()).hexdigest()
            conn.execute('INSERT OR REPLACE INTO users VALUES (?,?,?,?,?,?,?,?)',(data['id'],data['email'],data['name'],data['initials'],salt,ph,data['highest_level'],data['best_score']))
        elif sheet=='Levels':
            conn.execute('INSERT OR REPLACE INTO levels VALUES (?,?,?,?,?)',(data['level'],data['name'],data['base_speed'],data['speed_cap'],data['accent']))
        elif sheet=='Bricks':
            conn.execute('INSERT OR REPLACE INTO bricks VALUES (?,?,?,?,?)',(data['level'],data['row'],data['column'],data['type'],data['drop']))
        elif sheet=='Leaderboard':
            conn.execute('INSERT INTO leaderboard(initials,score,level,achieved_at,email) VALUES (?,?,?,?,?)',(data['initials'],data['score'],data['level'],data['achieved_at'],data.get('email')))
        elif sheet=='Constants':
            conn.execute('INSERT OR REPLACE INTO constants VALUES (?,?)',(data['key'],str(data['value'])))
# scenarios digest / import
conn.commit()
print('bootstrapped')
