const express = require('express');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const sqlite3 = require('sqlite3').verbose();

const app = express();
const dbPath = '/app/brickfall.db';
const publicDir = path.join('/app', 'public');
const db = new sqlite3.Database(dbPath);

app.use(express.json({ limit: '1mb' }));
app.use(express.static(publicDir));

function nowIso() { return new Date().toISOString(); }
function sha256(s) { return crypto.createHash('sha256').update(s).digest('hex'); }
function token() { return crypto.randomBytes(32).toString('hex'); }
function opId() { return crypto.randomUUID(); }
function q(sql, params=[]) { return new Promise((resolve,reject)=>db.get(sql, params, (e,row)=>e?reject(e):resolve(row))); }
function qall(sql, params=[]) { return new Promise((resolve,reject)=>db.all(sql, params, (e,rows)=>e?reject(e):resolve(rows))); }
function run(sql, params=[]) { return new Promise((resolve,reject)=>db.run(sql, params, function(e){e?reject(e):resolve(this);})); }
function send(res, status, body) { res.status(status).json(body); }
async function auth(req, res) {
  const h = req.headers.authorization || '';
  const m = h.match(/^Bearer\s+([a-f0-9]{64})$/);
  if (!m) return null;
  const row = await q('SELECT t.token, t.user_id, u.email, u.name, u.initials, u.highest_level, u.best_score FROM tokens t JOIN users u ON u.id=t.user_id WHERE t.token=? AND t.revoked_at IS NULL', [m[1]]);
  return row || null;
}
function requireAuth(handler){ return async (req,res)=>{ try{ const user=await auth(req,res); if(!user) return send(res,401,{error:'sign-in required'}); req.user=user; return handler(req,res);}catch(e){ console.error(e); send(res,500,{error:'server error'});} }; }
async function getConstants(){ const rows = await qall('SELECT key,value FROM constants'); return Object.fromEntries(rows.map(r=>[r.key,r.value])); }
function parseSnapshot(s){ return s ? JSON.parse(s) : null; }
async function loadRun(userId){ return q('SELECT * FROM runs WHERE user_id=? AND status IN (\'active\',\'paused\',\'completed\',\'game-over\') ORDER BY updated_at DESC LIMIT 1',[userId]); }
app.get('/api/bootstrap', requireAuth(async (req,res)=>{ const levels=await qall('SELECT * FROM levels ORDER BY level'); const bricks=await qall('SELECT * FROM bricks'); const leaderboard=await qall('SELECT initials,score,level,achieved_at FROM leaderboard ORDER BY score DESC, achieved_at ASC LIMIT 10'); const constants=await getConstants(); const run=await loadRun(req.user.user_id); send(res,200,{user:req.user, levels, bricks, leaderboard, constants, run: run ? parseSnapshot(run.snapshot_json) : null}); }));
app.post('/api/sign-in', async (req,res)=>{ const {email,password}=req.body||{}; const user=await q('SELECT * FROM users WHERE email=?',[email]); if(!user) return send(res,401,{error:'invalid credentials'}); const salt=user.password_salt; const hash=sha256(salt+password); if(hash!==user.password_hash) return send(res,401,{error:'invalid credentials'}); const t=token(); await run('INSERT INTO tokens(token,user_id,created_at,revoked_at) VALUES (?,?,?,NULL)',[t,user.id,nowIso()]); send(res,200,{token:t,user:{id:user.id,email:user.email,name:user.name,initials:user.initials,highest_level:user.highest_level,best_score:user.best_score}}); });
app.post('/api/sign-out', requireAuth(async (req,res)=>{ await run('UPDATE tokens SET revoked_at=? WHERE user_id=? AND revoked_at IS NULL',[nowIso(),req.user.user_id]); send(res,200,{ok:true}); }));
app.post('/api/run/start', requireAuth(async (req,res)=>{ const {level,operationId,expectedRevision}=req.body||{}; const existing=await q('SELECT * FROM run_receipts WHERE operation_id=?',[operationId]); if(existing){ res.status(existing.status_code).json(JSON.parse(existing.response_json)); return; } const lvl=await q('SELECT * FROM levels WHERE level=?',[level]); if(!lvl) return send(res,400,{error:'invalid level'}); const snapshot={runId:crypto.randomUUID(), level, score:0, lives:3, combo:1, nextExtraLife:20000, revision:1, status:'playing', balls:[{id:'ball1',x:400,y:520,vx:220,vy:-360,waiting:false}], drops:[], paddle:{x:340,width:120,sticky:false}, power:null, message:'Run started', unlockedLevel:Math.max(1,Math.min(level,req.user.highest_level)), activeRun:true}; await run('INSERT OR REPLACE INTO runs(run_id,user_id,status,revision,snapshot_json,updated_at,finished_at,operation_id) VALUES (?,?,?,?,?,?,?,?)',[snapshot.runId,req.user.user_id,'active',1,JSON.stringify(snapshot),nowIso(),null,operationId]); const response={run:snapshot}; await run('INSERT INTO run_receipts VALUES (?,?,?,?,?,?)',[operationId,req.user.user_id,200,JSON.stringify(response),sha256(JSON.stringify(req.body||{})),nowIso()]); send(res,200,response); }));
app.get('/api/me', requireAuth(async (req,res)=>{ const run=await loadRun(req.user.user_id); send(res,200,{user:req.user, run: run ? parseSnapshot(run.snapshot_json) : null}); }));
app.listen(3000,()=>console.log('Brickfall listening on 3000'));

