CREATE TABLE IF NOT EXISTS terminal_runs(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, run_id TEXT, outcome TEXT, level INTEGER, score INTEGER, finished_at TEXT, snapshot_json TEXT);
