        if sheet=='Users':
            salt = hashlib.sha256(f"{data['email']}|salt".encode()).hexdigest()[:16]
            ph = hashlib.sha256((salt+'password123').encode()).hexdigest()
            conn.execute('INSERT OR REPLACE INTO users VALUES (?,?,?,?,?,?,?,?)',(data['id'],data['email'],data['name'],data['initials'],salt,ph,data['highest_level'],data['best_score']))
        elif sheet=='Levels':
            conn.execute('INSERT OR REPLACE INTO levels VALUES (?,?,?,?,?)',(data['level'],data['name'],data['base_speed'],data['speed_cap'],data['accent']))
        elif sheet=='Bricks':
            conn.execute('INSERT OR REPLACE INTO bricks VALUES (?,?,?,?,?)',(data['level'],data['row'],data['column'],data['type'],data['drop']))
        elif sheet=='Leaderboard':
            conn.execute('INSERT INTO leaderboard(initials,score,level,achieved_at,email) VALUES (?,?,?,?,?)',(data['initials'],data['score'],data['level'],data['achieved_at'],data.get('email')))
        elif sheet=='Constants':
            conn.execute('INSERT OR REPLACE INTO constants VALUES (?,?)',(data['key'],str(data['value'])))
# scenarios digest / import
