app.post('/api/run/start',need(async(req,res)=>{const b=req.body||{}; const rr=receipt(b.operationId,req.user.user_id,b); if(rr?.conflict) return res.status(409).json({error:'operation id reuse with different payload'}); if(rr?.existing) return res.status(rr.existing.status_code).json(JSON.parse(rr.existing.response_json)); const lvl=get('SELECT * FROM levels WHERE level=?',[b.level]); if(!lvl) return res.status(400).json({error:'invalid level'}); const prev=runRow(req.user.user_id); if(prev && (b.expectedRevision||1)!==prev.revision) return res.status(409).json({error:'stale revision',revision:prev.revision,run:snap(prev)}); const runId=uid(); const sn={runId,level:b.level,score:0,lives:3,combo:1,nextExtraLife:20000,revision:(b.expectedRevision||1)+1,status:'playing',balls:[{id:'b1',x:400,y:520,vx:220,vy:-360,waiting:false}],drops:[],paddle:{x:340,width:120,sticky:false},power:null,message:'Run started',unlockedLevel:Math.min(req.user.highest_level,b.level),activeRun:true}; run('INSERT OR REPLACE INTO runs VALUES (?,?,?,?,?,?,?,?)',[runId,req.user.user_id,'active',sn.revision,JSON.stringify(sn),now(),null,b.operationId]); const resp={run:sn}; saveReceipt(b.operationId,req.user.user_id,200,resp,b); res.json(resp);}));
app.post('/api/run/save',need(async(req,res)=>{const b=req.body||{}; const rr=receipt(b.operationId,req.user.user_id,b); if(rr?.conflict) return res.status(409).json({error:'operation id reuse with different payload'}); if(rr?.existing) return res.status(rr.existing.status_code).json(JSON.parse(rr.existing.response_json)); const cur=runRow(req.user.user_id); if(!cur) return res.status(400).json({error:'no active run'}); if(b.expectedRevision!==cur.revision) return res.status(409).json({error:'stale revision',revision:cur.revision,run:snap(cur)}); const sn=b.run||snap(cur); sn.revision=cur.revision+1; run('UPDATE runs SET status=?,revision=?,snapshot_json=?,updated_at=?,operation_id=? WHERE run_id=?',['active',sn.revision,JSON.stringify(sn),now(),b.operationId,cur.run_id]); const resp={run:sn}; saveReceipt(b.operationId,req.user.user_id,200,resp,b); res.json(resp);}));
app.post('/api/run/finish',need(async(req,res)=>{const b=req.body||{}; const rr=receipt(b.operationId,req.user.user_id,b); if(rr?.conflict) return res.status(409).json({error:'operation id reuse with different payload'}); if(rr?.existing) return res.status(rr.existing.status_code).json(JSON.parse(rr.existing.response_json)); const cur=runRow(req.user.user_id); if(!cur) return res.status(400).json({error:'no active run'}); if(b.expectedRevision!==cur.revision) return res.status(409).json({error:'stale revision',revision:cur.revision,run:snap(cur)}); const sn=b.run||snap(cur); sn.revision=cur.revision+1; const outcome=b.outcome||sn.status||'completed'; run('UPDATE runs SET status=?,revision=?,snapshot_json=?,updated_at=?,finished_at=?,operation_id=? WHERE run_id=?',[outcome,sn.revision,JSON.stringify(sn),now(),now(),b.operationId,cur.run_id]); run('INSERT INTO terminal_runs(user_id,run_id,outcome,level,score,finished_at,snapshot_json) VALUES (?,?,?,?,?,?,?)',[req.user.user_id,cur.run_id,outcome,sn.level,sn.score,now(),JSON.stringify(sn)]); const u=get('SELECT * FROM users WHERE id=?',[req.user.user_id]); if(sn.score>u.best_score) run('UPDATE users SET best_score=? WHERE id=?',[sn.score,req.user.user_id]); if(sn.level>u.highest_level) run('UPDATE users SET highest_level=? WHERE id=?',[sn.level,req.user.user_id]); run('DELETE FROM runs WHERE run_id=?',[cur.run_id]); const lb=all('SELECT initials,score,level,achieved_at FROM leaderboard ORDER BY score DESC, achieved_at ASC'); const resp={terminal:{outcome,runId:cur.run_id,level:sn.level,score:sn.score,finishedAt:now()}, leaderboard:lb.slice(0,10)}; saveReceipt(b.operationId,req.user.user_id,200,resp,b); res.json(resp);}));
app.get('/api/lab',need(async(req,res)=>res.json({drills:all('SELECT key,value FROM constants')})))
